import { docs } from '../lib/docs.js'

export default {
	id: 'themes',
	title: 'Carbon themes',
	category: 'Basemap',
	summary: 'The White, Gray 10, Gray 90 and Gray 100 map themes on open vector tiles.',
	description: [
		'Carbon defines four map themes for spatial charts. Each one is a complete MapLibre style document generated by carbonStyle(theme) from a small palette of Carbon tokens, drawn on OpenFreeMap vector tiles. No access token is required.',
		'Use the theme switcher in the header: it calls map.setStyle() with the new style, and every example re-adds its own layers with colors from the matching data-vis palette.'
	],
	apis: [docs.map('setStyle'), docs.event('style.load'), docs.spec('Style root', 'root/'), docs.source('vector')],
	view: { center: [-73.9565, 40.7185], zoom: 13.6 },

	setup({ map, controls, onStyle }) {
		const basemap = controls.legend('Basemap tokens')
		const data = controls.legend('Categorical data palette')

		// Legends are DOM, not map layers, but they follow the theme through the same hook.
		onStyle(({ colors }) => {
			basemap.update([
				{ color: colors.background, label: `Background ${colors.background}` },
				{ color: colors.water, label: `Water ${colors.water}` },
				{ color: colors.park, label: `Park ${colors.park}` },
				{ color: colors.building, label: `Building ${colors.building}` },
				{ color: colors.roadMajor, label: `Major road ${colors.roadMajor}` },
				{ color: colors.roadMinor, label: `Minor road ${colors.roadMinor}` },
				{ color: colors.text, label: `Label ${colors.text}` }
			])
			data.update(colors.categorical.map((color, index) => ({ color, label: `${index + 1} · ${color}`, shape: 'circle' })))
		})

		const views = {
			Street: { center: [-73.9565, 40.7185], zoom: 13.6 },
			City: { center: [-73.98, 40.74], zoom: 10.5 },
			Country: { center: [-96, 38.5], zoom: 3.4 },
			World: { center: [10, 25], zoom: 1.4 }
		}
		controls.buttons(Object.entries(views).map(([label, view]) => [label, () => map.flyTo(view), 'tertiary']))

		const zoom = controls.readout('Zoom')
		const update = () => zoom(map.getZoom().toFixed(2))
		map.on('zoom', update)
		update()
	}
}
